static inline int extractLine(const unsigned char *pBuffer, int iDataLeft, char *pOutBuffer,
                              int iOutSize)
{
    int bytesRead = 0;
    unsigned char last = 0;

    pOutBuffer[0] = 0;
    while (iDataLeft - bytesRead > 0) {
        unsigned char c = pBuffer[bytesRead++];

        if (c == '\n' && last == '\r')
            break;
        if (c != '\r') {
            *pOutBuffer++ = c;
            *pOutBuffer = 0;
            if (--iOutSize == 1)
                break;
        }
        last = c;
    }
    pOutBuffer[--iOutSize] = 0;
    return bytesRead;
}

