                              int iOutSize)
{
    int bytesRead = 0;
    unsigned char last = 0;

    pOutBuffer[0] = 0;
    while (iDataLeft > 0) {
        unsigned char c = *pBuffer++;
        iDataLeft--;
        bytesRead++;

        if (c == '\n' && last == '\r') {
            *pOutBuffer = 0;
            break;
        }
        if (c != '\r' && c != '\n') {
            *pOutBuffer++ = c;
            *pOutBuffer = 0;
            iOutSize--;
            if (iOutSize == 1)
                break;
        }
        last = c;
    }
    pOutBuffer[--iOutSize] = 0;
    return bytesRead;
}

